/*
 * A032631  Primes that are concatenations of n with n + 8.
 * https://oeis.org/A032631
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the nth prime of the form concat(m, m+8) for some
 *            positive integer m. The sequence is generated by searching over
 *            increasing m, concatenating m and m+8, testing primality, and
 *            storing the primes in order
 * Range:     u8 n <= 1, u16 n <= 11, u32 n <= 11, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   concat_parts, is_prime_big, seq_alloc, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>

/* External utilities supplied by the build environment */
#include "../utils/is_prime_big.h"
#include "../utils/concat_parts.h"
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"

/* Cache of found primes */
static seq_t *cache      = NULL;   /* array of primes */
static size_t cache_cap  = 0;      /* allocated capacity */
static size_t cache_used = 0;      /* number of primes stored */

/* Next m to test */
static idx_t next_m = 1;

/* Ensure the cache has space for at least 'needs' elements. */
static void ensure_capacity(size_t needs)
{
    if (needs <= cache_cap)
        return;

    size_t new_cap = cache_cap ? cache_cap << 1 : 8;
    if (new_cap < needs)
        new_cap = needs;

    /* Use the provided allocation helpers to create a properly
       constructed array of seq_t objects. */
    seq_t *tmp = seq_realloc(cache, cache_cap, new_cap);
    if (!tmp)
        exit(EXIT_FAILURE);   /* out of memory */

    cache      = tmp;
    cache_cap  = new_cap;
}

/* Append a prime to the cache. */
static void cache_append(seq_t val)
{
    ensure_capacity(cache_used + 1);
    cache[cache_used++] = val;
}

/* Public sequence function. */
seq_t a(idx_t n)
{
    /* Offset is 1; value for n == 0 is undefined but return 0. */
    if (n == 0)
        return 0;

    /* Generate new primes until we have at least n of them. */
    while (cache_used < n) {
        seq_t cand = concat_parts(next_m, next_m + 8);
        if (is_prime_big(cand))
            cache_append(cand);
        ++next_m;
    }

    /* cache is zero‑based, n is one‑based */
    return cache[(size_t)(n - 1)];
}
